export const APP_NAME = "SalesCast";

// Shown in the header and footer so nobody mistakes demo data for real company data.
// Edit or empty this string if you load a real dataset.
export const DATASET_NOTE =
  "Synthetic demo dataset generated by scripts/generate_sales_data.py. It is not real company data.";

// Base URL of the API. Empty in development and in docker compose (same origin: Vite's proxy or nginx forwards /api).
// On Vercel the API lives on another host, so set VITE_API_URL (for example https://salescast-api.onrender.com).
export const API_BASE = (import.meta.env.VITE_API_URL ?? '').replace(/\/+$/, '')
